ActionReference.TargetX:
${mascot.lookRight
							? mascot.anchor.x + Math.round(256 * mascot.currentScale * scaling)
							: mascot.anchor.x - Math.round(256 * mascot.currentScale * scaling)}

ActionReference.LookRight:
${(function(){
				var others = mascot.manager.getMascotList();
				for(var i = 0; i < others.size(); i++){
					var o = others.get(i);
					if(o.imageSet !== 'Hornet') continue;
					return o.anchor.x > mascot.anchor.x;
				}
				return mascot.lookRight;
			})()}

${(function(){
				var others = mascot.manager.getMascotList();
				for(var i = 0; i < others.size(); i++){
					var o = others.get(i);
					if(o.imageSet !== 'Hornet') continue;
					return o.anchor.x > mascot.anchor.x;
				}
				return mascot.lookRight;
			})()}
